using System;
class RevivalChecks {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Main(){var clock=new CorpseClock();clock.Observe(true,9,0);Check(clock.Age(9)==9&&RevivalRules.Error("Revivify",clock,9)=="","revivify completion at one minute allowed");Check(RevivalRules.Error("Revivify",clock,10)!="","casting time counts against limit");clock.Clear();clock.Observe(true,9,0);clock.Preserve(1);Check(clock.Age(144001)==1,"preservation pauses exactly ten days");Check(clock.Age(144002)==2,"clock resumes after preservation expiry");clock.Preserve(144002);clock.Preserve(144003);Check(clock.Age(288003)==2,"recasting preservation extends without stacking age credit");clock.Observe(false,9,288004);Check(!clock.Dead,"revived body clears corpse record");clock.Observe(true,13,288005);Check(RevivalRules.Error("Raise Dead",clock,288005)!=""&&RevivalRules.Error("Revivify",clock,288005)=="","raise dead excludes undead but revivify does not");clock.Clear();clock.Observe(true,9,0);Check(RevivalRules.Error("Raise Dead",clock,143400)==""&&RevivalRules.Error("Raise Dead",clock,143401)!="","hour-long casting counts toward ten day limit");var c=new CombatState();c.KillPlayer();c.Aftermath=true;Check(c.Revive(true,1,true)&&c.PlayerHp==1&&!c.PlayerDead&&c.DeathFailures==0&&c.PlayerRevivalPenalty==-4,"revival restores one hp clears death state and adds ordeal");Check(c.Aftermath&&!c.PlayerCanAct,"revival does not automatically resume combat");for(int i=0;i<5;i++)c.CompleteLongRest(true);Check(c.PlayerRevivalPenalty==0,"four long rests clear ordeal without positive bonus");c.KillMonster();Check(c.Revive(false,1,true)&&c.Hp==1&&c.MonsterRevivalPenalty==-4,"monster revival");c.CompleteLongRest(false);Check(c.MonsterRevivalPenalty==-3&&c.PlayerRevivalPenalty==0,"rest relief applies to correct participant");Check(!c.Revive(false,1,false),"living target cannot be revived");c.Aftermath=false;c.EndRound();c.StartMonsterTurn();Check(c.PlayerHp==1&&c.Hp==1&&c.ActionsRemaining==1&&c.PlayerReactionAvailable&&c.MonsterReactionAvailable,"resume refreshes turn resources without healing");c.ResetBattle();Check(!c.Aftermath&&c.PlayerRevivalPenalty==0&&c.MonsterRevivalPenalty==0,"reset clears aftermath and revival penalties");Console.WriteLine("PASS: corpse clocks, preservation, casting duration, target types, revival, ordeal, rests, manual resume and reset");}
}
